"""
LeetCode 208. Implement Trie (Prefix Tree)

A trie (pronounced as "try") or prefix tree is a tree data structure used to
efficiently store and retrieve keys in a dataset of strings. There are
various applications of this data structure, such as autocomplete and
spellchecker.

Implement the Trie class:
    - Trie()                          Initializes the trie object.
    - void insert(String word)        Inserts the string word into the trie.
    - boolean search(String word)     Returns true if the string word is in
                                      the trie (i.e., was inserted before),
                                      and false otherwise.
    - boolean startsWith(String prefix)
                                      Returns true if there is a previously
                                      inserted string that has the prefix,
                                      and false otherwise.

Example:
    Input:
        ["Trie","insert","search","search","startsWith","insert","search"]
        [[],["apple"],["apple"],["app"],["app"],["app"],["app"]]
    Output:
        [null,null,true,false,true,null,true]

Constraints:
    - 1 <= word.length, prefix.length <= 2000
    - word and prefix consist only of lowercase English letters.
    - At most 3 * 10^4 calls in total will be made to insert, search,
      and startsWith.

Solution:
    Each Trie node holds:
        - children: dict mapping a single character to its child Trie node.
        - is_end:   True iff this node terminates a previously inserted word.
    insert / search / startsWith all walk down one node per character of the
    input string via the shared `_walk` helper.
"""


class TrieNode:
    def __init__(self):
        self.children = {}  # 映射字符 -> TrieNode
        self.is_end = False # 标识是否为一个完整单词的结尾

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def _walk(self, s: str):
        """Return the node reached by traversing `s` from the root, or None
        if any character in `s` is missing along the path."""
        node = self.root
        for ch in s:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_end = True

    def search(self, word: str) -> bool:
        node = self._walk(word)
        return node is not None and node.is_end

    def startsWith(self, prefix: str) -> bool:
        return self._walk(prefix) is not None
        


# Your Trie object will be instantiated and called as such:
if __name__ == "__main__":
    word = "Apple"
    obj = Trie()
    obj.insert(word)
    searchApple = obj.search(word)
    prefix = 'App'
    startWithApp = obj.startsWith(prefix)
    obj.insert('App')
    searchApp = obj.search('App')
    print(f'searchApple={searchApple}, startWithApp={startWithApp}, searchApp = {searchApp}')

"""
Overall Complexity
------------------
Let N be the total number of characters stored across all inserted words,
and L be the length of the word/prefix passed to a single call.

    insert:        Time O(L)         Space O(L) worst case (new nodes per char)
    search:        Time O(L)         Space O(1) iterative
    startsWith:    Time O(L)         Space O(1) iterative
    Trie overall:  Space O(N) total nodes across all inserted words.

Notes:
- All three operations run in linear time in the length of the input, which
  is asymptotically optimal because we must inspect each character at least
  once.
- The dict-based children gives expected O(1) character lookup (amortized),
  so the time bound is tight rather than O(L * alphabet).
- All methods are implemented iteratively, so the extra space beyond the
  output is O(1).
"""

